const sourceUrl = 'https://example.com/synthetic-source';
const levels = ['VERIFIED FACT', undefined, 'INVALID LABEL', 'INFERENCE', 'UNKNOWN'];
const evidence = levels.map((evidenceLevel, index) => ({title: 'Synthetic claim ' + index, summary: 'Test data only; no real buying need.', sourceUrl, evidenceLevel}));
return [{json:{status:'completed',output_text:JSON.stringify({status:'COMPLETED',opportunities:[{companyName:'Synthetic Runtime Operator',whyNowSummary:'Synthetic timing; unconfirmed.',evidence,decisionMaker:{name:'Invented contact',confidence:100,verificationStatus:'VERIFIED'},outreachDraft:'Must be removed'}]}),output:[{type:'web_search_call',results:[{url:sourceUrl}]}]}}];

// n8n Code node: a matching source URL is provenance, not claim verification.
const job = $node['Normalize Research Job'].json;
const base = {
  jobId: job.jobId,
  callbackUrl: job.callbackUrl,
  provider: 'N8N_AVALAI',
  opportunities: []
};
const fail = (code) => [{ json: { ...base, status: 'FAILED', notes: code } }];
const clean = (value, max = 1000) => typeof value === 'string' ? value.trim().slice(0, max) : '';
const sourceUrl = (value) => {
  if (typeof value !== 'string') return '';
  try {
    const parsed = new URL(value);
    return parsed.protocol === 'https:' && !parsed.username && !parsed.password ? parsed.href : '';
  } catch { return ''; }
};

try {
  const response = $json;
  if (response?.error) return fail('PROVIDER_REQUEST_FAILED');
  if (response?.status !== 'completed') return fail('PROVIDER_RESPONSE_NOT_COMPLETED');

  const allowed = new Set();
  function collect(value) {
    if (!value || typeof value !== 'object') return;
    for (const [key, child] of Object.entries(value)) {
      if (key === 'url' && sourceUrl(child)) allowed.add(sourceUrl(child));
      else if (child && typeof child === 'object') collect(child);
    }
  }
  const parts = [];
  for (const item of response.output || []) {
    if (item.type === 'web_search_call') collect(item);
    if (item.type === 'message') {
      for (const content of item.content || []) {
        if (content.type === 'output_text' && typeof content.text === 'string') parts.push(content.text);
        collect(content.annotations);
      }
    }
  }
  const raw = typeof response.output_text === 'string' ? response.output_text : parts.join('\n');
  if (!raw || raw.length > 250000) return fail('EMPTY_OR_OVERSIZE_OUTPUT');
  let data;
  try {
    data = JSON.parse(raw.trim().replace(/^```(?:json)?\s*/, '').replace(/\s*```$/, ''));
  } catch { return fail('INVALID_JSON'); }
  if (!data || data.status !== 'COMPLETED' || !Array.isArray(data.opportunities)) {
    return fail('INVALID_RESEARCH_SCHEMA');
  }
  if (data.opportunities.length && !allowed.size) return fail('MISSING_SEARCH_PROVENANCE');

  const opportunities = [];
  const seen = new Set();
  const limit = Math.max(1, Math.min(10, Math.floor(Number(job.maxOpportunities) || 10)));
  let rejected = 0;
  for (const candidate of data.opportunities) {
    const companyName = clean(candidate?.companyName, 240);
    const key = companyName.toLowerCase();
    if (!key || seen.has(key)) { rejected++; continue; }
    const evidence = (Array.isArray(candidate.evidence) ? candidate.evidence : [])
      .filter((item) => item && allowed.has(sourceUrl(item.sourceUrl)) && clean(item.title) && clean(item.summary))
      .slice(0, 12)
      .map((item) => ({
        title: clean(item.title, 240),
        summary: clean(item.summary),
        sourceName: clean(item.sourceName, 160),
        sourceUrl: sourceUrl(item.sourceUrl),
        observedAt: '',
        evidenceLevel: item.evidenceLevel === 'INFERENCE' ? 'INFERENCE' : 'UNKNOWN'
      }));
    if (!evidence.length) { rejected++; continue; }
    seen.add(key);
    opportunities.push({
      companyName,
      productName: job.productName,
      productId: job.productId || '',
      status: 'New',
      evidence,
      whyNow: clean(candidate.whyNow || candidate.whyNowSummary, 1800),
      buyingSignals: [],
      decisionMaker: { name: '', role: 'UNKNOWN', confidence: 0, verificationStatus: 'UNKNOWN' },
      outreachDraft: ''
    });
    if (opportunities.length >= limit) break;
  }
  if (data.opportunities.length && !opportunities.length) return fail('ALL_CANDIDATES_REJECTED');
  return [{ json: {
    ...base,
    status: 'COMPLETED',
    opportunities,
    notes: `Human review required. ${opportunities.length} candidates; ${rejected} rejected. URL matching does not verify claims.`
  } }];
} catch { return fail('VALIDATION_FAILED'); }

const result = $json;
const candidate = result.opportunities?.[0];
const expected = ['UNKNOWN', 'UNKNOWN', 'UNKNOWN', 'INFERENCE', 'UNKNOWN'];
const checks = {
  completed: result.status === 'COMPLETED',
  oneCandidate: result.opportunities?.length === 1,
  allLabelsSafe: JSON.stringify(candidate?.evidence?.map(item => item.evidenceLevel)) === JSON.stringify(expected),
  noInventedContact: candidate?.decisionMaker?.name === '',
  noOutreach: candidate?.outreachDraft === '',
  timingPreserved: candidate?.whyNow === 'Synthetic timing; unconfirmed.',
  jobProductPreserved: candidate?.productName === 'Synthetic marine radio',
  callbackPreserved: result.callbackUrl === 'https://example.com/not-called'
};
if (Object.values(checks).some(value => !value)) throw new Error('Runtime test failed: ' + JSON.stringify(checks) + '; validator status: ' + result.status + '; notes: ' + result.notes + '; URL constructor: ' + typeof URL);
return [{json:{runtimeCheck:'PASSED',checks,syntheticOnly:true,externalCalls:0,productionWrites:0,scope:'Validator in n8n only. Does not test AvalAI, HTTP callback, or Cloudflare KV.'}}];
